// Re-mint owner token, trigger fresh deploy, submit new certification task
const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

async function reMintToken() {
  console.log("=== Re-minting owner token ===");
  const r = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: OWNER_EMAIL }),
  });
  const text = await r.text();
  let j;
  try { j = JSON.parse(text); } catch { j = null; }
  console.log("status=" + r.status);
  if (!j || !j.accessToken) {
    console.log("body=" + text.slice(0, 500));
    return null;
  }
  await Bun.file("/tmp/owner_at").write(j.accessToken);
  if (j.refreshToken) await Bun.file("/tmp/owner_rt").write(j.refreshToken);
  console.log("token saved, len=" + j.accessToken.length);
  return j.accessToken;
}

let token = await Bun.file("/tmp/owner_at").text().catch(() => "");
// verify token works
try {
  const tv = await fetch(BASE + "/api/ivx/senior-developer/worker/status", {
    headers: { Authorization: "Bearer " + token },
  });
  console.log("existing token verify: " + tv.status);
  if (tv.status === 401) {
    token = await reMintToken();
    if (!token) { console.log("FAILED to re-mint"); process.exit(1); }
  }
} catch (e) {
  console.log("token check err: " + e);
  token = await reMintToken();
  if (!token) { console.log("FAILED to re-mint"); process.exit(1); }
}

// 1. Check current runtime state
console.log("\n=== Current runtime state ===");
const h = await fetch(BASE + "/health");
const hj = await h.json();
console.log("runtime SHA=" + hj.commit + " boot=" + hj.bootTime + " status=" + hj.status);

// 2. Check GitHub HEAD
console.log("\n=== GitHub HEAD ===");
const gh = await fetch("https://api.github.com/repos/ibb142/rork-global-real-estate-invest/commits/main");
const ghj = await gh.json();
console.log("github HEAD=" + ghj.sha + " msg=" + ghj.commit?.message?.slice(0, 80));

// 3. Trigger fresh Render deploy
console.log("\n=== Triggering fresh Render deploy ===");
const dr = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
  body: JSON.stringify({
    action: "render_trigger_deploy",
    input: {},
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
  }),
});
const dtext = await dr.text();
let dj;
try { dj = JSON.parse(dtext); } catch { dj = null; }
console.log("deploy trigger status=" + dr.status);
console.log("deploy trigger body=" + dtext.slice(0, 800));
const deployId = dj?.deployId ?? dj?.id ?? dj?.deploy?.id ?? null;
console.log("deployId=" + deployId);

// 4. Submit a NEW certification task with requestsDeploy=true
console.log("\n=== Submitting new certification task ===");
const taskPayload = {
  request: "IVX Senior Developer final certification task: autonomously create a proof marker file backend/services/ivx-senior-dev-final-cert-2026-07-19.ts that exports const FINAL_CERT = { task: 'autonomous-e2e-proof', timestamp: ISO string, proven: true }, commit it to GitHub, trigger a Render deploy, and live-verify the deployment with 3-way SHA parity. This task requests a deploy.",
  context: {
    trigger: "ivx-chat",
    priority: "critical",
    requestsDeploy: true,
    certificationTask: true,
  },
};
const tr = await fetch(BASE + "/api/ivx/owner-ai", {
  method: "POST",
  headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
  body: JSON.stringify(taskPayload),
});
const ttext = await tr.text();
let tj;
try { tj = JSON.parse(ttext); } catch { tj = null; }
console.log("task submit status=" + tr.status);
console.log("task submit body=" + ttext.slice(0, 800));
const taskId = tj?.taskId ?? tj?.task_id ?? tj?.id ?? null;
console.log("taskId=" + taskId);

// Save key facts for evidence collection
const facts = {
  triggeredAt: new Date().toISOString(),
  githubHeadBefore: ghj.sha,
  runtimeShaBefore: hj.commit,
  deployId,
  taskId,
  deployTriggerStatus: dr.status,
  taskSubmitStatus: tr.status,
};
await Bun.file("/tmp/cert-facts.json").write(JSON.stringify(facts, null, 2));
console.log("\n=== Facts saved to /tmp/cert-facts.json ===");
console.log(JSON.stringify(facts, null, 2));

