async function task(tid) {
  const r = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/" + tid, {
    headers: { Authorization: "Bearer " + token },
  });
  const d = await r.json();
  return { status: r.status, task: d.task ?? d, raw: d };
}

async function health() {
  const r = await fetch(BASE + "/health");
  return await r.json();
}

// 1. Get current task state (confirm WAITING_APPROVAL + capture commit)
console.log("=== Task state BEFORE approval ===");
const t0 = await task(TASK_ID);
console.log("status=" + t0.task?.status + " checkpoint=" + t0.task?.checkpoint);
console.log("commitSha=" + t0.task?.commitSha + " deployId=" + t0.task?.renderDeployId + " proof=" + t0.task?.proofLedgerId);
console.log("files=" + JSON.stringify(t0.task?.filesChanged));
console.log("error=" + t0.task?.errorMessage);

if (t0.task?.status !== "WAITING_APPROVAL") {
  console.log("\n!! Task NOT in WAITING_APPROVAL (status=" + t0.task?.status + "). Aborting approval. !!");
  process.exit(0);
}

// 2. Approve RENDER_DEPLOY
console.log("\n=== Approving RENDER_DEPLOY ===");
const ar = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/" + TASK_ID + "/approve", {
  method: "POST",
  headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
  body: JSON.stringify({
    action: "RENDER_DEPLOY",
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
  }),
});
const atext = await ar.text();
console.log("approve status=" + ar.status);
console.log("approve body=" + atext.slice(0, 800));

// 3. Poll task progress + runtime SHA
console.log("\n=== Polling task progress ===");
const start = Date.now();
let lastStatus = null;
for (let i = 1; i <= 6; i++) {
  const t = await task(TASK_ID);
  const h = await health();
  const ts = new Date().toISOString();
  const statusChanged = t.task?.status !== lastStatus;
  if (statusChanged) {
    console.log(`\n[${ts} #${i}] task.status=${t.task?.status} checkpoint=${t.task?.checkpoint}`);
    console.log(`  commitSha=${(t.task?.commitSha ?? "")?.slice(0,12)} deployId=${t.task?.renderDeployId} proof=${t.task?.proofLedgerId} runtime=${(t.task?.runtimeSha ?? "")?.slice(0,12)}`);
    console.log(`  runtime /health: sha=${(h.commit ?? "").slice(0,12)} boot=${(h.bootTime ?? "").slice(11,19)} status=${h.status}`);
    lastStatus = t.task?.status;
  } else {
    console.log(`[${ts} #${i}] task.status=${t.task?.status} (unchanged) runtime.sha=${(h.commit ?? "").slice(0,12)}`);
  }
  // Stop early if terminal
  if (t.task?.terminal === true || t.task?.status === "VERIFIED" || t.task?.status === "FAILED" || t.task?.status === "BLOCKED") {
    console.log("\n=== TERMINAL STATE REACHED ===");
    break;
  }
  await new Promise(r => setTimeout(r, 8000));
}

// 4. Final snapshot
console.log("\n=== FINAL SNAPSHOT ===");
const tf = await task(TASK_ID);
const hf = await health();
console.log("TASK:");
console.log("  taskId=" + tf.task?.taskId);
console.log("  status=" + tf.task?.status + " terminal=" + tf.task?.terminal);
console.log("  checkpoint=" + tf.task?.checkpoint);
console.log("  commitSha=" + tf.task?.commitSha);
console.log("  deployId=" + tf.task?.renderDeployId);
console.log("  runtimeSha=" + tf.task?.runtimeSha);
console.log("  proofLedgerId=" + tf.task?.proofLedgerId);
console.log("  filesChanged=" + JSON.stringify(tf.task?.filesChanged));
console.log("  errorMessage=" + tf.task?.errorMessage);
console.log("RUNTIME /health:");
console.log("  commit=" + hf.commit + " boot=" + hf.bootTime + " status=" + hf.status);

// 5. Save evidence
const evidence = {
  taskId: tf.task?.taskId,
  status: tf.task?.status,
  terminal: tf.task?.terminal,
  commitSha: tf.task?.commitSha,
  renderDeployId: tf.task?.renderDeployId,
  runtimeSha: tf.task?.runtimeSha,
  proofLedgerId: tf.task?.proofLedgerId,
  filesChanged: tf.task?.filesChanged,
  errorMessage: tf.task?.errorMessage,
  runtimeHealthCommit: hf.commit,
  runtimeHealthBoot: hf.bootTime,
  runtimeHealthStatus: hf.status,
  collectedAt: new Date().toISOString(),
};
await Bun.file("/tmp/cert-evidence.json").write(JSON.stringify(evidence, null, 2));
console.log("\n=== Evidence saved to /tmp/cert-evidence.json ===");
console.log(JSON.stringify(evidence, null, 2));

