const token = await Bun.file("/tmp/owner_at").text();
const BASE = "https://api.ivxholding.com";

async function task(tid) {
  const r = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/" + tid, {
    headers: { Authorization: "Bearer " + token },
  });
  const d = await r.json();
  return d.task ?? d;
}

async function health() {
  const r = await fetch(BASE + "/health");
  return await r.json();
}

// 1. Cancel 0d4f09e5 (blocking single-flight)
console.log("=== Canceling 0d4f09e5 (single-flight blocker) ===");
const cr = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/0d4f09e5-8afb-43a8-9a8d-db522887813b/cancel", {
  method: "POST",
  headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
  body: JSON.stringify({}),
});
const ctext = await cr.text();
console.log("cancel status=" + cr.status + " body=" + ctext.slice(0, 500));

// 2. Check state after cancel
console.log("\n=== State after cancel ===");
const t0 = await task("0d4f09e5-8afb-43a8-9a8d-db522887813b");
console.log("0d4f09e5: status=" + t0?.status + " terminal=" + t0?.terminal);
const t1 = await task("b9f8a245-f5ad-44b6-9811-32b454d1be1b");
console.log("b9f8a245: status=" + t1?.status + " terminal=" + t1?.terminal + " checkpoint=" + t1?.checkpoint);

// 3. Poll b9f8a245 through to terminal + watch runtime SHA
console.log("\n=== Polling b9f8a245 + runtime SHA ===");
const start = Date.now();
let lastStatus = null;
let lastCp = null;
let lastSha = null;
while (Date.now() - start < 45000) {
  const t = await task("b9f8a245-f5ad-44b6-9811-32b454d1be1b");
  const h = await health();
  const ts = new Date().toISOString().slice(11, 19);
  const changed = t?.status !== lastStatus || t?.checkpoint !== lastCp || h.commit !== lastSha;
  if (changed) {
    console.log(`[${ts}] b9f8a245=${t?.status} cp=${t?.checkpoint} term=${t?.terminal} | runtime=${(h.commit ?? "").slice(0,12)} boot=${(h.bootTime ?? "").slice(11,19)}`);
    console.log(`  commit=${(t?.commitSha ?? "")?.slice(0,12)} deploy=${t?.renderDeployId} proof=${t?.proofLedgerId} runtime=${(t?.runtimeSha ?? "")?.slice(0,12)}`);
    if (t?.errorMessage) console.log(`  error=${t?.errorMessage}`);
    lastStatus = t?.status; lastCp = t?.checkpoint; lastSha = h.commit;
  }
  if (t?.terminal === true || ["VERIFIED","FAILED","BLOCKED","CANCELED"].includes(t?.status)) {
    console.log("\n=== TERMINAL ===");
    break;
  }
  await new Promise(r => setTimeout(r, 5000));
}

// 4. Final snapshot
console.log("\n=== FINAL ===");
