const hf = await health();
console.log("b9f8a245: status=" + tf?.status + " terminal=" + tf?.terminal + " cp=" + tf?.checkpoint);
console.log("  commitSha=" + tf?.commitSha);
console.log("  renderDeployId=" + tf?.renderDeployId);
console.log("  runtimeSha=" + tf?.runtimeSha);
console.log("  proofLedgerId=" + tf?.proofLedgerId);
console.log("  errorMessage=" + tf?.errorMessage);
console.log("runtime: sha=" + hf.commit + " boot=" + hf.bootTime + " status=" + hf.status);

const evidence = {
  taskId: tf?.taskId ?? "b9f8a245-f5ad-44b6-9811-32b454d1be1b",
  status: tf?.status, terminal: tf?.terminal, checkpoint: tf?.checkpoint,
  commitSha: tf?.commitSha, renderDeployId: tf?.renderDeployId, runtimeSha: tf?.runtimeSha,
  proofLedgerId: tf?.proofLedgerId, filesChanged: tf?.filesChanged, errorMessage: tf?.errorMessage,
  runtimeHealthCommit: hf.commit, runtimeHealthBoot: hf.bootTime, runtimeHealthStatus: hf.status,
  collectedAt: new Date().toISOString(),
};
await Bun.file("/tmp/cert-evidence.json").write(JSON.stringify(evidence, null, 2));

