// Check deploy status via runtime endpoints + trigger fresh deploy if needed
const token = await Bun.file("/tmp/owner_at").text();
const BASE = "https://api.ivxholding.com";

async function get(url, label) {
  try {
    const r = await fetch(url, { headers: { Authorization: "Bearer " + token } });
    const text = await r.text();
    console.log(`\n=== ${label} (HTTP ${r.status}) ===`);
    console.log(text.slice(0, 2000));
    return { status: r.status, text };
  } catch (e) {
    console.log(`\n=== ${label} ERROR: ${e} ===`);
    return null;
  }
}

// 1. Runtime health
const h = await fetch(BASE + "/health");
const hj = await h.json();
console.log("=== RUNTIME /health ===");
console.log("sha=" + hj.commit + " boot=" + hj.bootTime + " status=" + hj.status);

// 2. Check deploy status endpoints
await get(BASE + "/api/ivx/developer-deploy/status", "DEPLOY STATUS");
await get(BASE + "/api/tool/render-status", "RENDER STATUS (api/tool)");
await get(BASE + "/tool/render-status", "RENDER STATUS (tool)");
await get(BASE + "/api/ivx/env-debug/render", "RENDER ENV DEBUG");

// 3. Trigger a FRESH deploy
console.log("\n=== Triggering FRESH Render deploy ===");
const dr = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
  body: JSON.stringify({
    action: "render_trigger_deploy",
    input: {},
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
  }),
});
const dtext = await dr.text();
console.log("status=" + dr.status);
console.log("body=" + dtext.slice(0, 1000));
let dj;
try { dj = JSON.parse(dtext); } catch {}
const deployId = dj?.result?.deployId ?? dj?.deployId ?? null;
console.log("deployId=" + deployId);

// 4. GitHub HEAD
const gh = await fetch("https://api.github.com/repos/ibb142/rork-global-real-estate-invest/commits/main");
const ghj = await gh.json();
console.log("\n=== GITHUB HEAD ===");
console.log("sha=" + ghj.sha + " msg=" + ghj.commit?.message?.slice(0, 80));

// Save deploy ID
const facts = {
  freshDeployId: deployId,
  freshDeployTriggeredAt: new Date().toISOString(),
  githubHead: ghj.sha,
  runtimeShaBefore: hj.commit,
};
await Bun.file("/tmp/cert-facts.json").write(JSON.stringify(facts, null, 2));
console.log("\nFacts: " + JSON.stringify(facts, null, 2));

