// Poll deploy status via /api/tool/render-status until update_in_progress → live/failed
const token = await Bun.file("/tmp/owner_at").text();
const BASE = "https://api.ivxholding.com";

async function getDeployStatus() {
  const r = await fetch(BASE + "/api/tool/render-status", {
    headers: { Authorization: "Bearer " + token },
  });
  const j = await r.json();
  const d = j?.data ?? {};
  return {
    deployId: d.deployId,
    deployStatus: d.deployStatus,
    deployedCommitSha: d.deployedCommitSha,
    deployCreatedAt: d.deployCreatedAt,
    deployFinishedAt: d.deployFinishedAt,
    history: (d.deployHistory ?? []).slice(0, 5).map(h => ({ id: h.deployId, status: h.status, sha: h.commitSha?.slice(0,12), created: h.createdAt?.slice(11,19), finished: h.finishedAt?.slice(11,19) })),
  };
}

async function health() {
  const r = await fetch(BASE + "/health");
  return await r.json();
}

const start = Date.now();
let lastStatus = null;
while (Date.now() - start < 50000) {
  const ds = await getDeployStatus();
  const h = await health();
  const ts = new Date().toISOString().slice(11, 19);
  const changed = ds.deployStatus !== lastStatus;
  console.log(`[${ts}] deploy=${ds.deployId} status=${ds.deployStatus} commit=${(ds.deployedCommitSha ?? "")?.slice(0,12)} | runtime=${(h.commit ?? "").slice(0,12)} boot=${(h.bootTime ?? "").slice(11,19)}`);
  if (changed) {
    console.log(`  history: ${JSON.stringify(ds.history)}`);
    lastStatus = ds.deployStatus;
  }
  // Stop if deploy finished (live or failed)
  if (ds.deployStatus === "live" || ds.deployStatus === "update_failed" || ds.deployStatus === "canceled" || ds.deployStatus === "deactivated") {
    console.log(`\n=== DEPLOY TERMINAL: ${ds.deployStatus} ===`);
    break;
  }
  // Stop if runtime SHA changed (deploy went live)
  if (h.commit !== "1d31e9c4db42b71d5f75c392ef19468470697f29") {
    console.log(`\n=== RUNTIME SHA CHANGED: ${h.commit} ===`);
    break;
  }
  await new Promise(r => setTimeout(r, 8000));
}

// Final
const ds = await getDeployStatus();
const h = await health();
console.log("\n=== FINAL ===");
console.log("deploy: " + ds.deployId + " status=" + ds.deployStatus + " commit=" + (ds.deployedCommitSha ?? "")?.slice(0,12));
console.log("runtime: " + h.commit + " boot=" + h.bootTime + " status=" + h.status);
console.log("history: " + JSON.stringify(ds.history, null, 2));

