   333|    const health = await getProductionHealth();
   334|
   335|    const githubSha = github.sha ?? null;
   336|    const renderSha = render.fullSha ?? null;
   337|    const runtimeShaFull = health.commit ?? null;
   338|    const runtimeSha = health.commitShort ?? (health.commit ? health.commit.slice(0, 8) : null);
   339|
   340|    const githubShort = githubSha ? githubSha.slice(0, 8) : null;
   341|    const renderShort = renderSha ? renderSha.slice(0, 8) : null;
   342|    const runtimeShort = runtimeSha ?? (runtimeShaFull ? runtimeShaFull.slice(0, 8) : null);
   343|
   344|    const match = githubShort !== null
   345|      && githubShort === renderShort
   346|      && renderShort === runtimeShort
   347|      && githubShort === expectedCommitSha.slice(0, 8);
   348|
   349|    const healthSnapshot: Record<string, unknown> = {
   350|      status: health.status,
   351|      ok: health.ok,
   352|      commitShort: health.commitShort,
   353|      bootTime: health.bootTime,
   354|      attempt,
