// Get full deploy details from render-status endpoint - look for error info
const token = await Bun.file("/tmp/owner_at").text();
const BASE = "https://api.ivxholding.com";

const r = await fetch(BASE + "/api/tool/render-status", {
  headers: { Authorization: "Bearer " + token },
});
const j = await r.json();
const d = j?.data ?? {};

// Print everything except deployHistory (already seen)
const { deployHistory, ...rest } = d;
console.log("=== FULL RENDER STATUS (excluding history) ===");
console.log(JSON.stringify(rest, null, 2));

// Print latest 3 deploys with ALL fields
console.log("\n=== LATEST 3 DEPLOYS (full detail) ===");
for (const h of (deployHistory ?? []).slice(0, 3)) {
  console.log(JSON.stringify(h, null, 2));
}

// Check if there's a logs URL or error message
console.log("\n=== Looking for error indicators ===");
for (const h of (deployHistory ?? []).slice(0, 3)) {
  console.log(`${h.deployId}: status=${h.status} | error fields: ${Object.keys(h).filter(k => k.toLowerCase().includes('error') || k.toLowerCase().includes('fail') || k.toLowerCase().includes('log') || k.toLowerCase().includes('reason')).join(',')}`);
  for (const k of Object.keys(h)) {
    if (k.toLowerCase().includes('error') || k.toLowerCase().includes('fail') || k.toLowerCase().includes('log') || k.toLowerCase().includes('reason')) {
      console.log(`  ${k}: ${h[k]}`);
    }
  }
}

