// Poll deploy dep-d9e3rdtaeets73acggqg + runtime SHA. If it goes LIVE, the boot scanner crash was the cause.
const token = await Bun.file("/tmp/owner_at").text();
const BASE = "https://api.ivxholding.com";
const OLD_SHA = "1d31e9c4db42b71d5f75c392ef19468470697f29";

async function getDeployStatus() {
  const r = await fetch(BASE + "/api/tool/render-status", {
    headers: { Authorization: "Bearer " + token },
  });
  const j = await r.json();
  const d = j?.data ?? {};
  return {
    deployId: d.deployId,
    deployStatus: d.deployStatus,
    deployedCommitSha: d.deployedCommitSha,
    history: (d.deployHistory ?? []).slice(0, 3).map(h => ({ id: h.deployId, status: h.status, sha: h.commitSha?.slice(0,12), created: h.createdAt?.slice(11,19), finished: h.finishedAt?.slice(11,19) })),
  };
}

async function health() {
  const r = await fetch(BASE + "/health");
  return await r.json();
}

const start = Date.now();
let lastStatus = null;
while (Date.now() - start < 52000) {
  const ds = await getDeployStatus();
  const h = await health();
  const ts = new Date().toISOString().slice(11, 19);
  if (ds.deployStatus !== lastStatus || h.commit !== OLD_SHA) {
    console.log(`[${ts}] deploy=${ds.deployId} status=${ds.deployStatus} commit=${(ds.deployedCommitSha ?? "")?.slice(0,12)} | runtime=${(h.commit ?? "").slice(0,12)} boot=${(h.bootTime ?? "").slice(11,19)} status=${h.status}`);
    console.log(`  history: ${JSON.stringify(ds.history)}`);
    lastStatus = ds.deployStatus;
  } else {
    console.log(`[${ts}] deploy=${ds.deployStatus} (unchanged) runtime=${(h.commit ?? "").slice(0,12)}`);
  }
  if (ds.deployStatus === "live" || ds.deployStatus === "update_failed") {
    console.log(`\n=== DEPLOY TERMINAL: ${ds.deployStatus} ===`);
    break;
  }
  if (h.commit !== OLD_SHA) {
    console.log(`\n=== RUNTIME SHA CHANGED: ${h.commit} ===`);
    break;
  }
  await new Promise(r => setTimeout(r, 7000));
}

const hf = await health();
console.log("\n=== FINAL ===");
console.log("runtime: sha=" + hf.commit + " boot=" + hf.bootTime + " status=" + hf.status);

