// Fetch the 5 Path B files at pre-Path-B commit 1d31e9c4 from GitHub API
const GITHUB = "https://api.github.com/repos/ibb142/rork-global-real-estate-invest";
const REF = "1d31e9c4db42b71d5f75c392ef19468470697f29";

const files = [
  "backend/services/ivx-senior-dev-worker.ts",
  "backend/services/ivx-senior-dev-proof.ts",
  "backend/services/ivx-owner-ai-task-queue.ts",
  "backend/services/ivx-enterprise-deployment-engine.ts",
  "backend/services/ivx-senior-dev-self-deploy-recovery.ts",
];

for (const path of files) {
  try {
    const r = await fetch(`${GITHUB}/contents/${path}?ref=${REF}`);
    const j = await r.json();
    if (j.content) {
      const content = Buffer.from(j.content, "base64").toString("utf8");
      const localPath = "/tmp/revert-" + path.split("/").pop();
      await Bun.file(localPath).write(content);
      console.log(`OK ${path} → ${localPath} (${content.length} bytes)`);
    } else {
      // File didn't exist at 1d31e9c4 (e.g., the new self-deploy-recovery.ts)
      console.log(`NOT_FOUND ${path} at ${REF.slice(0,12)} — ${j.message ?? "no content"}`);
    }
  } catch (e) {
    console.log(`ERR ${path}: ${e}`);
  }
}

