  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: OWNER_EMAIL }),
});
const rmj = await rm.json();
if (rmj.accessToken) await Bun.file("/tmp/owner_at").write(rmj.accessToken);
const token = rmj.accessToken || await Bun.file("/tmp/owner_at").text();

async function task(tid) {
  const r = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/" + tid, {
    headers: { Authorization: "Bearer " + token },
  });
  const d = await r.json();
  return { status: r.status, task: d.task ?? d };
}

async function health() {
  const r = await fetch(BASE + "/health");
  return { status: r.status, ...(await r.json()) };
}

// First check current state
console.log("=== Current task state ===");
const t0 = await task(TASK_ID);
console.log("status=" + t0.task?.status + " checkpoint=" + t0.task?.checkpoint);
console.log("commitSha=" + t0.task?.commitSha + " deployId=" + t0.task?.renderDeployId + " proof=" + t0.task?.proofLedgerId + " runtimeSha=" + t0.task?.runtimeSha);
console.log("files=" + JSON.stringify(t0.task?.filesChanged));
console.log("error=" + t0.task?.errorMessage);
console.log("terminal=" + t0.task?.terminal);

// Poll through to terminal
console.log("\n=== Polling through to terminal ===");
const start = Date.now();
let lastStatus = null;
let lastCp = null;
while (Date.now() - start < 50000) {
  const t = await task(TASK_ID);
  const ts = new Date().toISOString().slice(11, 19);
  if (t.task?.status !== lastStatus || t.task?.checkpoint !== lastCp) {
    console.log(`[${ts}] status=${t.task?.status} cp=${t.task?.checkpoint} terminal=${t.task?.terminal}`);
    console.log(`  commit=${(t.task?.commitSha ?? "")?.slice(0,12)} deploy=${t.task?.renderDeployId} proof=${t.task?.proofLedgerId} runtime=${(t.task?.runtimeSha ?? "")?.slice(0,12)}`);
    if (t.task?.errorMessage) console.log(`  error=${t.task?.errorMessage}`);
    lastStatus = t.task?.status;
    lastCp = t.task?.checkpoint;
  }
  if (t.task?.terminal === true || ["VERIFIED","FAILED","BLOCKED","CANCELED"].includes(t.task?.status)) {
    console.log("\n=== TERMINAL ===");
    break;
  }
  await new Promise(r => setTimeout(r, 5000));
}

// Final snapshot
console.log("\n=== FINAL SNAPSHOT ===");
